using TuoiTho.Core.Policy;
namespace TuoiTho.Storage;
public sealed class SqliteWebPolicyStore(SqliteDatabase database) : IWebPolicyStore
{
 public async Task<IReadOnlyList<WebRule>> GetRulesAsync(string profileId,CancellationToken cancellationToken=default){var result=new List<WebRule>();await using var c=await database.OpenConnectionAsync(cancellationToken);await using var q=c.CreateCommand();q.CommandText="SELECT provider,scope,decision,normalized_key,display_label FROM browser_content_rules WHERE profile_id=$id";q.Parameters.AddWithValue("$id",profileId);await using var r=await q.ExecuteReaderAsync(cancellationToken);while(await r.ReadAsync(cancellationToken))result.Add(new(profileId,Enum.Parse<BrowserProvider>(r.GetString(0)),Enum.Parse<WebRuleScope>(r.GetString(1)),Enum.Parse<WebRuleDecision>(r.GetString(2)),r.GetString(3),r.GetString(4)));return result;}
 public async Task SaveRuleAsync(WebRule rule,CancellationToken cancellationToken=default){await using var c=await database.OpenConnectionAsync(cancellationToken);await using var q=c.CreateCommand();q.CommandText="INSERT OR IGNORE INTO child_profiles(profile_id,display_name,created_at_utc) VALUES($id,$id,$now)";q.Parameters.AddWithValue("$id",rule.ProfileId);q.Parameters.AddWithValue("$now",DateTimeOffset.UtcNow.ToString("O"));await q.ExecuteNonQueryAsync(cancellationToken);q.Parameters.Clear();q.CommandText="INSERT INTO browser_content_rules(profile_id,provider,scope,normalized_key,display_label,decision,updated_at_utc) VALUES($id,$p,$s,$k,$d,$v,$now) ON CONFLICT(profile_id,provider,scope,normalized_key) DO UPDATE SET display_label=excluded.display_label,decision=excluded.decision,updated_at_utc=excluded.updated_at_utc";q.Parameters.AddWithValue("$id",rule.ProfileId);q.Parameters.AddWithValue("$p",rule.Provider.ToString());q.Parameters.AddWithValue("$s",rule.Scope.ToString());q.Parameters.AddWithValue("$k",rule.NormalizedKey);q.Parameters.AddWithValue("$d",rule.DisplayLabel);q.Parameters.AddWithValue("$v",rule.Decision.ToString());q.Parameters.AddWithValue("$now",DateTimeOffset.UtcNow.ToString("O"));await q.ExecuteNonQueryAsync(cancellationToken);}
 public async Task RemoveRuleAsync(string profileId,BrowserProvider provider,WebRuleScope scope,string normalizedKey,CancellationToken cancellationToken=default){await using var c=await database.OpenConnectionAsync(cancellationToken);await using var q=c.CreateCommand();q.CommandText="DELETE FROM browser_content_rules WHERE profile_id=$id AND provider=$p AND scope=$s AND normalized_key=$k";q.Parameters.AddWithValue("$id",profileId);q.Parameters.AddWithValue("$p",provider.ToString());q.Parameters.AddWithValue("$s",scope.ToString());q.Parameters.AddWithValue("$k",normalizedKey);await q.ExecuteNonQueryAsync(cancellationToken);}
}